<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="text-muted small"><?=e($client['company_name'])?></div><h1 class="h3 mb-0">Privacy tasks</h1></div><a class="btn btn-primary" href="tasks/create?client_id=<?=(int)$client['id']?>">New task</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Task</th><th>Priority</th><th>Status</th><th>Assignee</th><th>Due</th><th></th></tr></thead><tbody><?php foreach($tasks as $t):?><tr><td><div class="fw-semibold"><?=e($t['title'])?></div><small class="text-muted"><?=e($t['description']??'')?></small></td><td><?=e(ucfirst($t['priority']))?></td><td><?=e(ucwords(str_replace('_',' ',$t['status'])))?></td><td><?=e($t['assignee_name']??'Unassigned')?></td><td><?=e($t['due_date']??'—')?></td><td><form method="post" action="tasks/status?client_id=<?=(int)$client['id']?>" class="d-flex gap-1"><?php include __DIR__.'/../partials/csrf.php';?><input type="hidden" name="id" value="<?=(int)$t['id']?>"><select name="status" class="form-select form-select-sm"><option value="open">Open</option><option value="in_progress">In progress</option><option value="blocked">Blocked</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><button class="btn btn-sm btn-outline-primary">Update</button></form></td></tr><?php endforeach;?><?php if(!$tasks):?><tr><td colspan="6" class="text-center text-muted py-5">No privacy tasks yet.</td></tr><?php endif;?></tbody></table></div></div></div>
